def seed_database():
    Base.metadata.create_all(bind=engine)
    db = SessionLocal()
    try:
        demo_user = db.query(models.User).filter(models.User.email == "demo@travelverse.com").first()
        if not demo_user:
            demo_user = models.User(
                id=1,
                name="Alex Morgan",
                email="demo@travelverse.com",
                password_hash=hash_password("password123"),
                avatar_url="https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=200&q=80"
            )
            db.add(demo_user)
            db.commit()

        db.query(models.Destination).delete()
        db.commit()

        models_list = []
        for idx, item in enumerate(UNIQUE_DESTINATIONS):
            # Guarantee 100% unique image URL per destination ID
            unique_photo_url = f"{item['image_url']}?dest_id={idx+1}&auto=format&fit=crop&w=800&q=80"
            models_list.append(models.Destination(
                id=idx + 1,
                name=item["name"],
                country=item["country"],
                category=item["category"],
                description=item["description"],
                latitude=item["latitude"],
                longitude=item["longitude"],
                rating=item["rating"],
                budget_level=item["budget_level"],
                duration=item["duration"],
                weather=item["weather"],
                image_url=unique_photo_url,
                highlights=item["highlights"]
            ))

        db.add_all(models_list)
        db.commit()
        print(f"SUCCESS: SEEDED {len(models_list)} UNIQUE DESTINATIONS WITH 100% UNIQUE PHOTOS!")
    except Exception as e:
        print("Seeding error:", e)
        db.rollback()
    finally:
        db.close()

if __name__ == "__main__":
    seed_database()
